<section class="admin-page-head"><div><p class="admin-kicker">AUTORIZACIÓN</p><h1>Roles y permisos</h1><p>Los permisos se verifican en el servidor y se aplican de inmediato.</p></div></section>
<div class="admin-grid-2 admin-grid-align-start"><section class="admin-panel"><h2>Roles disponibles</h2><?php if ($roles === []): ?><p class="admin-empty">No hay roles configurados.</p><?php else: ?><ul class="admin-card-list"><?php foreach ($roles as $role): ?><li><div><strong><?= e($role['name']) ?></strong><small><?= e($role['code']) ?></small></div><?php if ((int) $role['is_system'] === 1): ?><span class="admin-status is-active">Sistema</span><?php elseif ($capabilities['roles.edit'] ?? false): ?><a class="admin-secondary-button" href="/admin/roles/edit?id=<?= e($role['id']) ?>">Editar</a><?php else: ?><span class="admin-status">Configurable</span><?php endif ?><p><?= e($role['description'] ?? 'Sin descripción') ?></p></li><?php endforeach ?></ul><?php endif ?></section>
<?php if ($capabilities['roles.create'] ?? false): ?><section class="admin-panel"><h2>Crear rol</h2><p class="admin-panel-copy">Los roles del sistema no se eliminan. El nuevo rol podrá asignarse globalmente o por sucursal.</p><form method="post" action="/admin/roles/create" class="admin-form"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><label class="admin-field"><span>Clave estable</span><input name="code" required maxlength="64" pattern="[A-Za-z][A-Za-z0-9_]{1,63}" placeholder="GERENTE_SUCURSAL"></label><label class="admin-field"><span>Nombre</span><input name="name" required maxlength="120"></label><label class="admin-field"><span>Descripción</span><textarea name="description" maxlength="500" rows="3"></textarea></label><fieldset class="admin-fieldset"><legend>Permisos</legend><div class="admin-permission-list"><?php foreach ($permissions as $permission): ?><label class="admin-check"><input type="checkbox" name="permission_ids[]" value="<?= e($permission['id']) ?>"><span><strong><?= e($permission['description']) ?></strong><small><?= e($permission['code']) ?> · <?= e($permission['scope']) ?></small></span></label><?php endforeach ?></div></fieldset><button class="admin-primary-button" type="submit">Crear rol</button></form></section><?php endif ?></div>
